// Extract CV model predictions and original request payload
const webhookData = $('Webhook Trigger (Multipart)').first().json.body || $('Webhook Trigger (Multipart)').first().json;
const cvResponse = $input.first().json;

// Image geometry (defaulting to 1920x1080 if not returned by inference model)
const imgWidth = cvResponse.image?.width || 1920;
const imgHeight = cvResponse.image?.height || 1080;

// Brand color mapping matching QFI corporate visual identity
const BRAND_COLORS = {
  'YARA': '#4B0082',
  'ADEERA': '#16A34A',
  'OTHER': '#DC2626',
  'ZAIN': '#2563EB',
  'AL RAI': '#059669',
  'DAWI': '#9333EA'
};

// Initialize counts
const counts = {
  'YARA': 0,
  'ZAIN': 0,
  'AL RAI': 0,
  'ADEERA': 0,
  'DAWI': 0,
  'OTHER': 0
};

const predictions = cvResponse.predictions || [];
const boxes = [];

// Bay overlap (sent by the app for Bay 2+): the left part of this photo up to the count line
// was already counted in the previous bay. Boxes whose centre is left of the line are returned
// flagged and are NOT counted. seam_cut_frac is a fraction of the image width.
const seamCutFrac = Number(webhookData.seam_cut_frac);
const seamActive = Number.isFinite(seamCutFrac) && seamCutFrac > 0 && seamCutFrac < 1;
const seamCutX = seamActive ? seamCutFrac * imgWidth : 0;
const countsBeforeSeam = { ...counts };
let excludedBySeam = 0;

// Process each bounding box detected by the Computer Vision model
predictions.forEach((pred, index) => {
  const rawClass = (pred.class || 'OTHER').toUpperCase();
  const matchedBrand = Object.keys(counts).includes(rawClass) ? rawClass : 'OTHER';

  countsBeforeSeam[matchedBrand] = (countsBeforeSeam[matchedBrand] || 0) + 1;
  const excluded = seamActive && pred.x < seamCutX; // pred.x is the box centre
  if (excluded) excludedBySeam++;
  else counts[matchedBrand] = (counts[matchedBrand] || 0) + 1;

  const left = Math.round(pred.x - pred.width / 2);
  const top = Math.round(pred.y - pred.height / 2);
  const width = Math.round(pred.width);
  const height = Math.round(pred.height);

  boxes.push({
    id: `box-${index + 1}`,
    brand: matchedBrand,
    confidence: Number((pred.confidence || 0.99).toFixed(2)),
    x: left,
    y: top,
    width: width,
    height: height,
    color: BRAND_COLORS[matchedBrand] || '#DC2626',
    thickness: 5,
    fontSize: 18,
    labelBackground: BRAND_COLORS[matchedBrand] || '#DC2626',
    label: matchedBrand,
    excluded_by_seam: excluded
  });
});

const totalFacings = Object.values(counts).reduce((a, b) => a + b, 0);
const needsReview = predictions.some(p => (p.confidence || 1) < 0.65);
const seamLine = seamActive ? `\nOverlap with ${webhookData.seam_previous_bay || 'previous bay'}: ${excludedBySeam} counted there` : '';

const replyText = `QFI Shelf Audit\nTotal facings: ${totalFacings}\nYARA: ${counts['YARA']}\nZAIN: ${counts['ZAIN']}\nAL RAI: ${counts['AL RAI']}\nADEERA: ${counts['ADEERA']}\nDAWI: ${counts['DAWI']}\nOTHER: ${counts['OTHER']}\nNeeds review: ${needsReview ? 'Yes' : 'No'}${seamLine}`;

return [{
  json: {
    success: true,
    chatId: 8223336613,
    replyText,
    total_facings: totalFacings,
    counts,
    boxes,
    needs_review: needsReview,
    bay_key: webhookData.bay_key || null,
    seam_applied: seamActive,
    seam_cut_frac: seamActive ? seamCutFrac : null,
    counts_before_seam: countsBeforeSeam,
    excluded_by_seam: excludedBySeam,
    // Only report the size when the model returned it (the app trusts this for box placement)
    ...(cvResponse.image?.width && cvResponse.image?.height ? { image: { width: cvResponse.image.width, height: cvResponse.image.height } } : {}),
    annotation_style: {
      thickness: 5,
      fontSize: 18,
      solidLabelBackground: true,
      labelContent: 'brand only'
    }
  }
}];
